                "description": "§7When wearing the §bMask of the Heretic§7,\n§nHaul§r§7 will instead bounce you off\nthe ground §f3§7 times at an increasing\nspeed and damage nearby enemies.\n\n§nFrog Dance§7 does not require §nTotem§7 to be used.\n\n§c⚔§7 Total Damage: §f200%§8 (of your DPS)\n    (§6✣§8 Damage: 150%)\n    (§b❉ §8Water: 50%)\n§3☀ §7Area of Effect: §f4.5 Blocks §7(Circle-Shaped)",
                "unlockingWillBlock": [],
