                "description": "§7Greatly reduce §nMain Attack§7 spread.\n\nYour §nMain Attack§7 will now inflict enemies\nwith §bBleeding §c §7for §f+0.25s §7per beam.\n\n§bBleeding §c §7enemies take damage every §f0.5s§7.\n§bBleeding §c §7damage dealt within §nTotem§7's range\nalso adds §f+0.8 §7points to your §bBlood Pool §4⚕§7.\n\n§c⚔ §7Total Damage: §f60% §8(of your DPS, from Bleeding)\n   §8(§6✣ §8Damage: 60%)",
