                "description": "§7Increases the damage of §bSacred Surge §6✧§7.\n\n§c⚔ §7Total Damage: §f+250% §8(of your DPS)\n   §8(§6✣ §8Damage: +200%)\n   §8(§b❉ §8Water: +25%)\n   §8(§f❋ §8Air: +25%)",
