                "description": "§7Keeps you alive with §f30%§7 of your health\nremaining and makes all nearby allies invincible\nafter receiving a fatal blow.\n\n§e✧ §7Effect: §fInvincibility (§b☗§f) to Allies\n§d⌛ §7Duration: §f3s\n§3☀ §7Area of Effect: §f12 Blocks §7(Circle-Shaped)\n§3⌚ §7Cooldown: §f10m",
